SELECT p.gender, COUNT(CASE WHEN l.value < 1.5 THEN 1 END) AS normal_count, COUNT(CASE WHEN l.value BETWEEN 1.5 AND 2.5 THEN 1 END) AS borderline_count, COUNT(CASE WHEN l.value > 2.5 THEN 1 END) AS elevated_count FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_hosp.admissions a ON p.subject_id = a.subject_id JOIN physionet-data.mimiciv_3_1_hosp.labevents l ON a.hadm_id = l.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 40 AND 50 AND l.itemid = 83107580-2 AND l.value IS NOT NULL GROUP BY p.gender;